import base64,hashlib,json
from pathlib import Path
r=Path("/data/forte-public-data/meva-counter-train-v1")
b=base64.b64decode('')
p=r/"subset.manifest.json"
with p.open("xb") as f:f.write(b)
print(json.dumps({"subset_manifest_path":str(p),"sha256":hashlib.sha256(p.read_bytes()).hexdigest(),"video_files":len(list((r/"originals").glob("*.avi")))}))
